import{_ as t,o,c as a,a3 as i}from"./chunks/framework.iKZ1V-y0.js";const u=JSON.parse('{"title":"Long-Period Clocks","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"长周期时钟","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=l2Igx2VZPkosoaw14MCvfA","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-l2Igx2VZPkosoaw14MCvfA.md","filePath":"logistics/src/page-l2Igx2VZPkosoaw14MCvfA.md","lastUpdated":null}'),s={name:"logistics/src/page-l2Igx2VZPkosoaw14MCvfA.md"};function r(n,e,l,p,c,d){return o(),a("div",null,[...e[0]||(e[0]=[i('<div class="logistics-content"><span class="logistics-source-anchor" id="长周期时钟" aria-hidden="true"></span><span class="logistics-source-anchor" id="long-period-clock-signals" aria-hidden="true"></span><span class="logistics-source-anchor" id="长周期时钟信号" aria-hidden="true"></span><h1 id="long-period-clocks" tabindex="-1">Long-Period Clocks <a class="header-anchor" href="#long-period-clocks" aria-label="Permalink to &quot;Long-Period Clocks&quot;">​</a></h1><blockquote><p>Source page ID: <code>l2Igx2VZPkosoaw14MCvfA</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=l2Igx2VZPkosoaw14MCvfA" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>For related research, perhaps see<br><a href="https://www.bilibili.com/video/BV1PrAazxE7Y" target="_blank" rel="noreferrer">Cursed Engineering: This Is the End of Cursed Engineering! Quiet, Everyone—Time Is Mine to Allocate!</a></p><p><a href="https://github.com/hongshan-academy/discussion/discussions/3" target="_blank" rel="noreferrer">Offline Power-Replenishment Device: An Ultra-Low-Power Generator</a></p><p><a href="./page-6F2DUSvH8Fb5nUCOVpTyay">T Flip-Flop</a></p><blockquote><p>I feel this could perhaps be merged into the T flip-flop page.</p></blockquote><blockquote><p>A T flip-flop is a method; this page describes a requirement and whether a method can satisfy it. Later we could add a line to the T flip-flop page listing this as a requirement it can meet. But the requirement itself is not subordinate to one of its implementation methods, so I do not think they should be merged.</p></blockquote><p>Implementation using a flow regularizer / mixed Stash</p><p>The core principle is that item B outside a Stash, different from item A inside it, must wait until A has entirely flowed out before entering. By limiting the Stash&#39;s output rate, we obtain a period equal to the quantity of rate-limited item A in the Stash * 1 / rate limit, allowing B to enter only after each period. For a concrete structure, see 君&#39;s full-storage oscillation scheme.</p><p>Implementation using belt vacancies / pattern copying</p><p>The core principle is a mixed-item belt loop. Item B can enter vacancies between items A on the loop through a low-priority merge. Changing the positions and spacing of belt vacancies adjusts the output phase. Cascading structures with aligned phases can also produce a period equal to the least common multiple.</p><p>Implementation using a flow limiter in the narrow sense</p><p>See <a href="./page-hDaaudSDbsi3GGvVV2XWBL">Flow Theory for Idealized Systems</a>: a 1/n-type limiter realizes any period. Replacing the input Converger in <a href="https://docs.qq.com/aio/DZXhhTUp6WU1Yd3Ba?p=GzlRUGEnEkorT2H6NOunIL&amp;client_hint=0#IXIRHlju0U32xxRj7QSvA6" target="_blank" rel="noreferrer">this structure</a> with a Protocol Stash also yields a simpler, more convenient general-purpose flow-limiter construction.</p></div>',1)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
